"use strict";(self.webpackChunkmy_website=self.webpackChunkmy_website||[]).push([["266"],{6164(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/docs/what-is-fuegocable","label":"What is fuegocable?","docId":"what-is-fuegocable","unlisted":false},{"type":"category","label":"Introduction","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/intro/motivation","label":"Motivation of the project","docId":"intro/motivation","unlisted":false},{"type":"link","href":"/docs/intro/firewire-usage","label":"How can firewire audio interfaces be used today?","docId":"intro/firewire-usage","unlisted":false},{"type":"link","href":"/docs/intro/firewire-vs-usb","label":"Firewire vs. USB","docId":"intro/firewire-vs-usb","unlisted":false},{"type":"link","href":"/docs/intro/about-mod","label":"About the fuegocable Mod","docId":"intro/about-mod","unlisted":false},{"type":"link","href":"/docs/intro/future","label":"The future of fuegocable","docId":"intro/future","unlisted":false}]},{"type":"category","label":"Technical overview","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/technical-overview/how-mod-works","label":"How does the mod work?","docId":"technical-overview/how-mod-works","unlisted":false},{"type":"link","href":"/docs/technical-overview/audio-drivers","label":"How do audio drivers work?","docId":"technical-overview/audio-drivers","unlisted":false}]},{"type":"category","label":"Modding guides","collapsible":true,"collapsed":true,"items":[{"type":"category","label":"Presonus","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/modding-guides/presonus/firestudio-project","label":"Firestudio Project","docId":"modding-guides/presonus/firestudio-project","unlisted":false},{"type":"link","href":"/docs/modding-guides/presonus/fp10","label":"FP10","docId":"modding-guides/presonus/fp10","unlisted":false}]},{"type":"category","label":"Focusrite","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/modding-guides/focusrite/saffire","label":"Saffire","docId":"modding-guides/focusrite/saffire","unlisted":false}]}]},{"type":"category","label":"How to contribute","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/how-to-contribute/hardware","label":"Hardware","docId":"how-to-contribute/hardware","unlisted":false},{"type":"link","href":"/docs/how-to-contribute/research-photos-datasheets","label":"Research, photos & datasheets","docId":"how-to-contribute/research-photos-datasheets","unlisted":false},{"type":"link","href":"/docs/how-to-contribute/software","label":"Software","docId":"how-to-contribute/software","unlisted":false},{"type":"link","href":"/docs/how-to-contribute/testing-bug-reports","label":"Testing & bug reports","docId":"how-to-contribute/testing-bug-reports","unlisted":false}]}]},"docs":{"how-to-contribute/hardware":{"id":"how-to-contribute/hardware","title":"Hardware","description":"Custom and open source XMOS board for USB-I2S/TDM","sidebar":"tutorialSidebar"},"how-to-contribute/research-photos-datasheets":{"id":"how-to-contribute/research-photos-datasheets","title":"Research, photos & datasheets","description":"If you have access to a FireWire audio interface that has not yet been modified, any information you can share about it can be very useful:","sidebar":"tutorialSidebar"},"how-to-contribute/software":{"id":"how-to-contribute/software","title":"Software","description":"Submit any pull requests that you think would add value to any fuegocable repository. The main firmware of the project is available at https://github.com/fuegocable/xmos-firmware, and eventually satellite applications will be added to interface with other features of the devices, such as audio mixers and signal routers.","sidebar":"tutorialSidebar"},"how-to-contribute/testing-bug-reports":{"id":"how-to-contribute/testing-bug-reports","title":"Testing & bug reports","description":"If you are a user of an audio interface modified with fuegocable, it is extremely important to share your feedback about how the mod is working. You can open an issue in the project\'s firmware repository, located at https://github.com/fuegocable/xmos-firmware, to describe bugs or suggest improvements in detail, so someone can review and implement them. The more detail and information you can provide in the issue, the better!","sidebar":"tutorialSidebar"},"intro/about-mod":{"id":"intro/about-mod","title":"About the fuegocable Mod","description":"The modification proposed by fuegocable is based on replacing the device that acts as the main controller of an audio interface, allowing the new controller to communicate directly with the digital audio signals coming from the converters and transfer them over USB. The modification also requires implementing the necessary configuration and control of the relevant integrated circuits and peripherals.","sidebar":"tutorialSidebar"},"intro/firewire-usage":{"id":"intro/firewire-usage","title":"How can firewire audio interfaces be used today?","description":"It is not impossible to use old Firewire audio interfaces today. To verify this, one only needs to turn on a desktop PC from a few years ago with a compatible Firewire port, install an appropriate operating system and driver, and use an older version of a DAW such as Pro Tools to record or play back audio.","sidebar":"tutorialSidebar"},"intro/firewire-vs-usb":{"id":"intro/firewire-vs-usb","title":"Firewire vs. USB","description":"A great deal has been said among musicians, technicians, and online about whether Firewire is better than USB, or about which of the two standards is superior. This section is not intended to change anyone\'s preferences or to question what a musician or technician may experience with their hardware and find useful for their art or work. Rather, the goal is to provide some clarity when comparing two audio interfaces.","sidebar":"tutorialSidebar"},"intro/future":{"id":"intro/future","title":"The future of fuegocable","description":"Does fuegocable get updates? Who maintains it?","sidebar":"tutorialSidebar"},"intro/motivation":{"id":"intro/motivation","title":"Motivation of the project","description":"It is not uncommon to find old Firewire audio interfaces being sold on various marketplaces at very low prices. Many of them are high-quality pieces of hardware that originally had a much higher market value, but are now much more affordable because getting them to work with modern computers is no longer straightforward.","sidebar":"tutorialSidebar"},"modding-guides/focusrite/saffire":{"id":"modding-guides/focusrite/saffire","title":"Saffire","description":"This is a work-in-progress!","sidebar":"tutorialSidebar"},"modding-guides/presonus/firestudio-project":{"id":"modding-guides/presonus/firestudio-project","title":"Firestudio Project","description":"Support Level","sidebar":"tutorialSidebar"},"modding-guides/presonus/fp10":{"id":"modding-guides/presonus/fp10","title":"FP10","description":"This is a work-in-progress!","sidebar":"tutorialSidebar"},"technical-overview/audio-drivers":{"id":"technical-overview/audio-drivers","title":"How do audio drivers work?","description":"This section explains how the USB connection between a fuegocable-modified audio interface and a computer\'s operating system is handled.","sidebar":"tutorialSidebar"},"technical-overview/how-mod-works":{"id":"technical-overview/how-mod-works","title":"How does the mod work?","description":"Reverse engineering","sidebar":"tutorialSidebar"},"what-is-fuegocable":{"id":"what-is-fuegocable","title":"What is fuegocable?","description":"The project is still in the alpha stage. For now, only the Presonus Firestudio Project interface has been successfully modified. More models will be added over time as they undergo reverse engineering.","sidebar":"tutorialSidebar"}}}}')}}]);